mapper.select:
SELECT login_id
FROM tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}
LIMIT 1

SELECT user_id
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND login_id = #{loginId}
LIMIT 1

SELECT login_id
FROM (
  SELECT la.login_id
  FROM tb_login_account la
  WHERE la.tenant_id = #{tenantId}
    AND la.login_id = #{candidateId}
  UNION ALL
  SELECT u.login_id
  FROM tb_user u
  WHERE u.tenant_id = #{tenantId}
    AND u.user_id = #{candidateId}
) q
LIMIT 1

SELECT login_id
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND exe_seq = #{exeSeq}
  AND COALESCE(muldec_status, '') = 'drafted'
LIMIT 1

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND COALESCE(muldec_status, '') = 'drafted'

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND COALESCE(muldec_status, '') = 'drafted'
  AND COALESCE(app_status, '') IN ('approved', 'returned')

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND login_id = #{loginId}
  AND COALESCE(muldec_status, '') = 'drafted'
  AND COALESCE(app_status, '') IN ('approved', 'returned')

SELECT login_id
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND login_id = #{loginId}
  AND COALESCE(muldec_status, '') = 'cooperated'
LIMIT 1

mapper.update:
UPDATE tb_electronic_approval_line_info
SET
  app_status = #{appStatus},
  option_name = #{optionName},
  exe_at = #{updatedAt, jdbcType=TIMESTAMP},
  open_at = #{updatedAt, jdbcType=TIMESTAMP}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND exe_seq = #{exeSeq}
  AND COALESCE(muldec_status, '') = 'drafted'

UPDATE tb_electronic_approval_line_info
SET
  arrival_at = #{arrivalAt, jdbcType=TIMESTAMP},
  option_name = #{optionName},
  exe_at = NULL,
  open_at = NULL
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND exe_seq = #{exeSeq}
  AND COALESCE(muldec_status, '') = 'drafted'

UPDATE tb_electronic_approval_line_info
SET
  app_status = #{appStatus},
  option_name = #{optionName},
  exe_at = #{updatedAt, jdbcType=TIMESTAMP},
  open_at = #{updatedAt, jdbcType=TIMESTAMP}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND login_id = #{loginId}
  AND COALESCE(muldec_status, '') = 'cooperated'

UPDATE tb_electronic_approval_main
SET
  status_type = #{statusType},
  status_type_name = #{statusTypeName},
  end_status = #{endStatus},
  updated_by = #{updatedBy, jdbcType=BIGINT},
  updated_at = #{updatedAt, jdbcType=TIMESTAMP}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}

mapper.select:
SELECT electronic_approval_id
FROM tb_electronic_approval_main
WHERE tenant_id = #{tenantId}
  AND drafting_work_category_id = #{workId}
  AND login_id = #{loginId}
  AND COALESCE(delete_status, 'N') != 'Y'
  AND COALESCE(status_type, '') = 'pre_apply'
ORDER BY COALESCE(updated_at, created_at) DESC, electronic_approval_id DESC
LIMIT 1

mapper.delete:
DELETE FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
AND electronic_approval_id = #{approvalId}
